#!/usr/bin/env bash
# Codex PreToolUse(shell) hook (harness/codex/tea-rags/scripts/deny-indexed-read.sh,
# generated by scripts/gen-harness-codex.ts; bd tea-rags-mcp-mqhlr): Codex has no
# Read tool, so a file the tea-rags index serves is read through shell `sed -n` /
# `cat`. The hook asks `tea-rags project indexed --command --cwd --json` and
# denies (exit 2, reason on stderr) when a reader operand is indexed; it fails
# open on everything else.
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$ROOT/harness/codex/tea-rags/scripts/deny-indexed-read.sh"
PASS=0; FAIL=0
note() { if [ "$1" = 0 ]; then PASS=$((PASS+1)); echo "ok   - $2"; else FAIL=$((FAIL+1)); echo "FAIL - $2"; fi; }

# Fake `tea-rags` on PATH:
#   `project indexed --command <c> --cwd <d> --json` records <c> and cwd:<d>, prints $FAKE_OUT, exits $FAKE_EXIT
FAKEBIN="$(mktemp -d)"; CALLS="$(mktemp)"
cat > "$FAKEBIN/tea-rags" <<'EOF'
#!/usr/bin/env bash
[ "$1 $2 $3" = "project indexed --command" ] || exit 3
printf '%s\n' "$4" >> "$CALLS"
echo "cwd:$6" >> "$CALLS"
printf '%s\n' "$FAKE_OUT"
exit "$FAKE_EXIT"
EOF
chmod +x "$FAKEBIN/tea-rags"
# A PATH holding jq and the base system but no tea-rags (the CLI-missing case).
NOCLI="$(mktemp -d)"; ln -s "$(command -v jq)" "$NOCLI/jq"
BASE_PATH="/usr/bin:/bin"
export CALLS

run() { # $1=json payload, $2=fake stdout, $3=fake exit, [$4=PATH]
  : > "$CALLS"; export FAKE_OUT="$2" FAKE_EXIT="$3"
  ERR=$(printf '%s' "$1" | PATH="${4:-$FAKEBIN:$NOCLI:$BASE_PATH}" bash "$HOOK" 2>&1 >/dev/null)
  CODE=$?
}
shell_of() { jq -cn --arg c "$1" '{hook_event_name:"PreToolUse",tool_name:"Bash",tool_input:{command:$c},cwd:"/repo/sub"}'; }
asked() { grep -qxF -- "$1" "$CALLS"; }
allowed() { [ "$CODE" = 0 ] && [ -z "$ERR" ]; }
denied() { [ "$CODE" = 2 ] && printf '%s' "$ERR" | grep -qF "$1"; }

INDEXED='{"indexed":true,"project":"repo","collectionName":"code_repo","relativePath":"src/a.ts"}'

[ -f "$HOOK" ]
note $? "hook script is generated"

# 1. sed -n of an indexed file → exit 2, reason names find_symbol with the tree-relative path
run "$(shell_of 'sed -n 1,80p src/a.ts')" "$INDEXED" 0
denied 'find_symbol(relativePath: "src/a.ts")'; note $? "sed -n of an indexed file is denied"
denied 'find_symbol(symbols: [<the method ids you need>])'; note $? "deny reason offers find_symbol(symbols) for known ids"
denied 'outside the index'; note $? "deny reason says what shell reads are for"
{ asked 'sed -n 1,80p src/a.ts' && asked cwd:/repo/sub; }; note $? "the CLI gets the command and the hook cwd"

# 2. compound with an indexed reader operand → denied, ONE CLI call carries the whole command
run "$(shell_of 'cat a.rb && sed -n 1,40p src/a.ts')" "$INDEXED" 0
denied 'find_symbol(relativePath: "src/a.ts")'; note $? "compound read of an indexed file is denied"
[ "$(grep -c . "$CALLS")" = 2 ]; note $? "one CLI call for the whole compound"

# 3. git diff | head → the CLI answers not indexed → allowed
run "$(shell_of 'git diff | head -50')" '{"indexed":false}' 1
allowed; note $? "git diff | head is allowed"

# 4. reader of a non-indexed file → allowed
run "$(shell_of 'cat package.json')" '{"indexed":false}' 1
allowed; note $? "read of a non-indexed file is allowed"

# 5. CLI missing from PATH → allowed
run "$(shell_of 'sed -n 1,80p src/a.ts')" "$INDEXED" 0 "$NOCLI:$BASE_PATH"
allowed; note $? "missing tea-rags CLI fails open"

# 6. CLI error (usage exit 2) → allowed
run "$(shell_of 'sed -n 1,80p src/a.ts')" "garbage" 2
allowed; note $? "CLI error exit fails open"

# 7. exit 0 but unparsable output → allowed
run "$(shell_of 'sed -n 1,80p src/a.ts')" "not json" 0
allowed; note $? "unparsable CLI output fails open"

# 8. no reader in the command → the CLI is never asked
run "$(shell_of 'npm test && git status')" "$INDEXED" 0
{ allowed && [ ! -s "$CALLS" ]; }; note $? "command without a reader skips the CLI"

# 9. argv-array command: bash -lc '<code>' → the CLI gets <code>
run "$(jq -cn '{tool_name:"shell",tool_input:{command:["bash","-lc","sed -n 1,80p src/a.ts"]},cwd:"/repo/sub"}')" "$INDEXED" 0
{ denied 'find_symbol(relativePath: "src/a.ts")' && asked 'sed -n 1,80p src/a.ts'; }; note $? "argv bash -lc read of an indexed file is denied"

# 10. argv-array command without a shell → joined, a word needing quotes shell-quoted
run "$(jq -cn '{tool_name:"shell",tool_input:{command:["cat","src/a.ts"]},cwd:"/repo/sub"}')" "$INDEXED" 0
{ denied 'find_symbol(relativePath: "src/a.ts")' && asked 'cat src/a.ts'; }; note $? "argv reader of an indexed file is denied"

run "$(jq -cn '{tool_name:"shell",tool_input:{command:["cat","my file.ts"]},cwd:"/repo/sub"}')" '{"indexed":false}' 1
asked "cat 'my file.ts'"; note $? "argv word with a space is shell-quoted for the CLI"

# 11. tool_input.workdir overrides the session cwd; a relative one resolves against it
run "$(jq -cn '{tool_name:"shell",tool_input:{command:"cat src/a.ts",workdir:"pkg"},cwd:"/repo"}')" "$INDEXED" 0
asked cwd:/repo/pkg; note $? "relative workdir resolves against the session cwd"

# 12. malformed stdin → allowed
run 'not json' "$INDEXED" 0
allowed; note $? "malformed hook input fails open"

rm -rf "$FAKEBIN" "$NOCLI" "$CALLS"
echo "# $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
